{
  "version": "1.0",
  "task_id": "factoryforge_sorting_probe_20261026_a1",
  "intent": "按高度分拣线：面板Start启动后输送带运行并周期性供料；高纸箱经推料机构推入侧面滑槽从outlet_tall计数出口离开，矮纸箱沿直行从outlet_short计数出口离开；Stop停止，NC急停断开立即停止并锁存禁止自动重启，急停释放后Reset清除锁存方可重启；conveyor_fault或pusher_fault时停止相关动作并点亮报警，故障消失后可重新启动。验收正常高低分流、停机、急停与复位、机构故障处理、仿真健康。",
  "runtime": {
    "backend": "mujoco",
    "startup_timeout_s": 30
  },
  "sampling": {
    "scope": "all_mapped",
    "period_ms": 20
  },
  "timeout_s": 90,
  "initial_inputs": {
    "sensor_low_detect": false,
    "sensor_high_detect": false,
    "pusher_extended": false,
    "pusher_retracted": false,
    "conveyor_fault": false,
    "pusher_fault": false,
    "panel_start": false,
    "panel_stop": false,
    "panel_reset": false,
    "panel_estop_ok": true,
    "counter_tall": 0,
    "counter_short": 0,
    "panel_delay_ms": 300
  },
  "actions": [
    {
      "op": "start_simulation"
    },
    {
      "op": "wait",
      "seconds": 0.3
    },
    {
      "op": "set",
      "values": {
        "panel_estop_ok": true,
        "panel_delay_ms": 300
      }
    },
    {
      "op": "wait",
      "seconds": 0.2
    },
    {
      "op": "pulse",
      "signal": "panel_reset",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait",
      "seconds": 0.2
    },
    {
      "op": "pulse",
      "signal": "panel_start",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": true
        }
      ],
      "timeout_s": 5
    },
    {
      "op": "wait",
      "seconds": 1.0
    },
    {
      "op": "set",
      "values": {
        "sensor_high_detect": true,
        "sensor_low_detect": false
      }
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "pusher_extend",
          "equals": true
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "pusher_extended",
          "equals": true
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "set",
      "values": {
        "sensor_high_detect": false,
        "sensor_low_detect": false
      }
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "pusher_extend",
          "equals": false
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "pusher_retracted",
          "equals": true
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "wait",
      "seconds": 1.0
    },
    {
      "op": "set",
      "values": {
        "sensor_low_detect": true,
        "sensor_high_detect": false
      }
    },
    {
      "op": "wait",
      "seconds": 1.5
    },
    {
      "op": "set",
      "values": {
        "sensor_low_detect": false,
        "sensor_high_detect": false
      }
    },
    {
      "op": "wait",
      "seconds": 1.0
    },
    {
      "op": "pulse",
      "signal": "panel_stop",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": false
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "pulse",
      "signal": "panel_start",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait_until",
