          "equals": true
        }
      ],
      "timeout_s": 5
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "set",
      "values": {
        "panel_estop_ok": false
      }
    },
    {
      "op": "wait",
      "seconds": 0.3
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": false
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "set",
      "values": {
        "panel_estop_ok": true
      }
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "pulse",
      "signal": "panel_reset",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait",
      "seconds": 0.3
    },
    {
      "op": "pulse",
      "signal": "panel_start",
      "value": true,
