        {
          "signal": "conveyor_run",
          "equals": true
        }
      ],
      "timeout_s": 5
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "set",
      "values": {
        "pusher_fault": true
      }
    },
    {
      "op": "wait",
      "seconds": 0.5
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "pusher_extend",
          "equals": false
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "set",
      "values": {
        "pusher_fault": false
      }
    },
    {
