    },
    {
      "op": "pulse",
      "signal": "panel_start",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": true
        }
      ],
      "timeout_s": 5
    },
    {
      "op": "wait",
      "seconds": 2.0
    },
    {
      "op": "pulse",
      "signal": "panel_stop",
      "value": true,
      "restore": false,
      "duration_ms": 200
    },
    {
      "op": "wait_until",
      "all": [
        {
          "signal": "conveyor_run",
          "equals": false
        }
      ],
      "timeout_s": 3
    },
    {
      "op": "wait",
      "seconds": 0.3
    }
  ],
  "completion": {
    "all": [
      {
        "signal": "conveyor_run",
        "equals": false
      },
      {
        "signal": "pusher_extend",
        "equals": false
      },
      {
        "signal": "emitter_emit",
        "equals": false
      },
      {
        "signal": "pusher_extended",
        "equals": false
      },
      {
        "signal": "pusher_retracted",
        "equals": true
      },
      {
        "signal": "counter_tall",
        "target": 1,
        "tolerance": 1
      },
      {
        "signal": "counter_short",
        "target": 1,
        "tolerance": 1
      }
    ],
    "settle_s": 0.3
  },
  "cleanup_inputs": {
    "sensor_low_detect": false,
    "sensor_high_detect": false,
    "pusher_extended": false,
    "pusher_retracted": false,
    "conveyor_fault": false,
    "pusher_fault": false,
    "panel_start": false,
    "panel_stop": false,
    "panel_reset": false,
    "panel_estop_ok": true,
    "counter_tall": 0,
    "counter_short": 0,
    "panel_delay_ms": 300
  },
  "path_checks": [
    {
      "id": "PATH_PUSHER_TALL",
      "desc": "高件推料循环：推杆由收回位伸出至到位反馈pusher_extended，保持后收回至pusher_retracted到位反馈，确认伸缩实际到位与计数行为一致。",
      "points": [
        {
          "values": {
            "pusher_retracted": true,
            "pusher_extended": false
          },
          "tolerance": {
            "pusher_retracted": 0,
            "pusher_extended": 0
          },
          "states": {
            "pusher_extend": false
          }
        },
        {
          "values": {
            "pusher_extended": true,
            "pusher_retracted": false
          },
          "tolerance": {
            "pusher_extended": 0,
            "pusher_retracted": 0
          },
          "states": {
            "pusher_extend": true
          }
        },
        {
          "values": {
            "pusher_retracted": true,
            "pusher_extended": false
          },
          "tolerance": {
            "pusher_retracted": 0,
            "pusher_extended": 0
          },
          "states": {
            "pusher_extend": false
          }
        }
      ]
    },
    {
      "id": "PATH_SORT_SHORT_TALL",
      "desc": "高矮件分流顺序：先高件推入侧面滑槽并经outlet_tall计数，后矮件沿直行经outlet_short计数，最终推杆收回、输送停、计数各为1。",
      "points": [
        {
          "values": {
            "counter_tall": 0,
            "counter_short": 0
          },
          "tolerance": {
            "counter_tall": 0,
            "counter_short": 0
          },
          "states": {
            "conveyor_run": true,
            "pusher_retracted": true
          }
        },
        {
          "values": {
            "counter_tall": 1,
            "counter_short": 0
          },
          "tolerance": {
            "counter_tall": 1,
            "counter_short": 0
          },
          "states": {
            "conveyor_run": true,
            "pusher_retracted": true
          }
        },
        {
          "values": {
